import { DateGridDateItem } from '../types';
import dayjs, { Dayjs } from 'dayjs';
import quarterOfYear from 'dayjs/plugin/quarterOfYear';
import { ViewModeConfig } from './utils';

dayjs.extend(quarterOfYear);

function generateDateGridItems(viewDate: Dayjs): DateGridDateItem[] {
  const year = viewDate.year();
  const quarters: DateGridDateItem[] = [];

  for (let i = 1; i <= 4; i++) {
    const quarterDate = viewDate.year(year).quarter(i).startOf('quarter');
    quarters.push({
      type: 'date',
      label: `Q${i}`,
      value: quarterDate,
    });
  }
  return quarters;
}

export const quarterInYearViewMode: ViewModeConfig = {
  generateDateGridItems,
  period: 'year',
  unit: 'quarter',
  header: { showYear: true },
  columns: 4,
};
