import { Locale } from '@fe-infra/keystone-locales';
import { Dayjs } from 'dayjs';
import { DateGridItem } from '../types';
import { DatePeriod } from '../utils';

export interface ViewModeConfig {
  generateDateGridItems: (viewDate: Dayjs, locale: Locale) => DateGridItem[];
  period: DatePeriod;
  unit: 'day' | 'month' | 'quarter' | 'year';
  header: { showDecade?: boolean; showYear?: boolean; showMonth?: boolean };
  columns: number;
  minRows?: number;
  compactVerticalGap?: boolean;
}

export function eachDayOfInterval(start: Dayjs, end: Dayjs): Dayjs[] {
  if (start.isAfter(end)) {
    return [];
  }
  const dateArray = [];
  let current = start;
  while (current.isSame(end, 'day') || current.isBefore(end, 'day')) {
    dateArray.push(current);
    current = current.add(1, 'day');
  }
  return dateArray;
}
