import { DateGridDateItem } from '../types';
import { Dayjs } from 'dayjs';
import { ViewModeConfig } from './utils';

function generateDateGridItems(viewDate: Dayjs): DateGridDateItem[] {
  const startYearOfDecade = Math.floor(viewDate.year() / 10) * 10;
  const years: DateGridDateItem[] = [];

  // Pad with one year at the beginning and one at the end of the decade for a 4x3 grid.
  const firstYearInGrid = startYearOfDecade - 1;
  const lastYearInGrid = startYearOfDecade + 10;

  for (let year = firstYearInGrid; year <= lastYearInGrid; year++) {
    const yearDate = viewDate.year(year);
    years.push({
      type: 'date',
      label: String(year),
      value: yearDate,
    });
  }
  return years;
}

export const yearInDecadeViewMode: ViewModeConfig = {
  generateDateGridItems,
  period: 'decade',
  header: { showDecade: true },
  unit: 'year',
  columns: 3,
};
