import { DatePickerViewMode } from '../types';
import { dateInMonthViewMode } from './date-in-month';
import { monthInYearViewMode } from './month-in-year';
import { quarterInYearViewMode } from './quarter-in-year';
import { ViewModeConfig } from './utils';
import { yearInDecadeViewMode } from './year-in-decade';

export const viewModeConfigs: Record<DatePickerViewMode, ViewModeConfig> = {
  dateInMonth: dateInMonthViewMode,
  monthInYear: monthInYearViewMode,
  quarterInYear: quarterInYearViewMode,
  yearInDecade: yearInDecadeViewMode,
};

export function getViewModeConfig(viewMode: DatePickerViewMode): ViewModeConfig {
  return viewModeConfigs[viewMode];
}

const sortedAllUnits: ViewModeConfig['unit'][] = ['year', 'quarter', 'month', 'day'];
const sortedAllViewModes = Object.entries(viewModeConfigs)
  .sort((a, b) => sortedAllUnits.indexOf(a[1].unit) - sortedAllUnits.indexOf(b[1].unit))
  .map((viewMode) => viewMode[0] as DatePickerViewMode);
export function findSubViewMode(
  currentViewMode: DatePickerViewMode,
  availableViewModes: DatePickerViewMode[],
): DatePickerViewMode | undefined {
  const currentIndex = sortedAllViewModes.indexOf(currentViewMode);

  if (currentIndex === -1) {
    return;
  }

  return sortedAllViewModes.slice(currentIndex + 1).find((viewMode) => availableViewModes.includes(viewMode));
}
