import { Locale } from '@fe-infra/keystone-locales';
import { DateGridDateItem, DateGridIndicatorItem, DateGridItem } from '../types';
import { Dayjs } from 'dayjs';
import { eachDayOfInterval, ViewModeConfig } from './utils';
import { dayjsToNativeDate, getFirstDayOfWeek, upperFirst } from '../utils';
import { cacheOrUpdate } from '@src/shared/perf/cache';

const WEEKDAY_MAX_SAFE_LENGTH = 4;
const WEEKDAY_IDEAL_LENGTH = 2;
const shortWeekdayFormatter = cacheOrUpdate(
  'en',
  (locale: Locale) => new Intl.DateTimeFormat(locale, { weekday: 'short' }),
);
const narrowWeekdayFormatter = cacheOrUpdate(
  'en',
  (locale: Locale) => new Intl.DateTimeFormat(locale, { weekday: 'narrow' }),
);

function getLocalizedWeekday(date: Date, locale: Locale = 'en') {
  let weekday = shortWeekdayFormatter(locale).format(date);
  if (weekday.length >= WEEKDAY_MAX_SAFE_LENGTH) {
    const narrowWeekday = narrowWeekdayFormatter(locale).format(date);
    if (!(weekday.length === WEEKDAY_MAX_SAFE_LENGTH && narrowWeekday.length !== WEEKDAY_IDEAL_LENGTH)) {
      weekday = narrowWeekday;
    }
  }
  weekday = upperFirst(weekday, locale);
  return weekday;
}

function generateDateGridItems(viewDate: Dayjs, locale: Locale): DateGridItem[] {
  const firstDayOfWeek = getFirstDayOfWeek(locale);
  const firstDayOfMonth = viewDate.startOf('month');

  // dayjs().day() is not locale-aware, it always returns 0 for Sunday.
  // We need to manually calculate the first day of the calendar view
  // based on the locale's first day of the week.
  const dayOfWeekOfFirstOfMonth = firstDayOfMonth.day();
  const daysToPadAtBeginning = (dayOfWeekOfFirstOfMonth - firstDayOfWeek + 7) % 7;
  const firstDayOfCalendar = firstDayOfMonth.subtract(daysToPadAtBeginning, 'day');

  // Most calendar views are 6 weeks long (42 days) to have a consistent layout.
  const calendarViewTotalDays = 42;
  const lastDayOfCalendar = firstDayOfCalendar.add(calendarViewTotalDays - 1, 'day');

  const dateGridItems: DateGridDateItem[] = eachDayOfInterval(firstDayOfCalendar, lastDayOfCalendar).map((item) => ({
    type: 'date',
    label: String(item.date()),
    value: item,
  }));
  const weekdayDecorativeHeaderGridItems: DateGridIndicatorItem[] = dateGridItems.slice(0, 7).map((item) => ({
    type: 'indicator',
    label: getLocalizedWeekday(dayjsToNativeDate(item.value), locale),
  })) as DateGridIndicatorItem[];

  return [...weekdayDecorativeHeaderGridItems, ...dateGridItems];
}

export const dateInMonthViewMode: ViewModeConfig = {
  generateDateGridItems,
  period: 'month',
  unit: 'day',
  header: { showYear: true, showMonth: true },
  columns: 7,
  minRows: 6,
  compactVerticalGap: true,
};
