import { Locale } from '@fe-infra/keystone-locales';
import { DateGridDateItem } from '../types';
import { Dayjs } from 'dayjs';
import { ViewModeConfig } from './utils';
import { dayjsToNativeDate, getLocalizedMonth } from '../utils';

function generateDateGridItems(viewDate: Dayjs, locale: Locale): DateGridDateItem[] {
  const year = viewDate.year();
  const months: DateGridDateItem[] = [];

  for (let i = 0; i < 12; i++) {
    const monthDate = viewDate.year(year).month(i);
    months.push({
      type: 'date',
      label: getLocalizedMonth(dayjsToNativeDate(monthDate), locale),
      value: monthDate,
    });
  }
  return months;
}

export const monthInYearViewMode: ViewModeConfig = {
  generateDateGridItems,
  period: 'year',
  unit: 'month',
  header: { showYear: true },
  columns: 3,
};
